directory = {0: 'table0'}
table0 = {i: (i * 4096, True) for i in range(16)}
def translate(addr):
    d = (addr >> 22) & 0x3FF
    t = (addr >> 12) & 0x3FF
    off = addr & 0xFFF
    if d not in directory:
        return 'fault: directory entry not present'
    frame, present = table0[t]
    if not present:
        return 'fault: page not present'
    return hex(frame + off)
for a in [0x0000, 0x1000, 0xF123]:
    print(hex(a), '->', translate(a))

handlers = {}
def timer():
    return 'timer tick handled'
def keyboard():
    return 'keystroke handled'
def default(n):
    return f'no handler for vector {n}'
handlers[8] = timer
handlers[9] = keyboard
for vec in [8, 9, 33]:
    fn = handlers.get(vec)
    print(f'vector {vec}:', fn() if fn else default(vec))

codes = {0x1E: 'a', 0x30: 'b', 0x39: ' ', 0x1C: '\n'}
stream = [0x2A, 0x1E, 0xAA, 0x30, 0x39, 0x1E]
shift = False
out = []
for c in stream:
    if c == 0x2A:
        shift = True
    elif c == 0xAA:
        shift = False
    elif c in codes:
        ch = codes[c]
        out.append(ch.upper() if shift and ch.isalpha() else ch)
print('typed:', ''.join(out).replace(chr(10), '<enter>'))

def sys_write(s):
    return f'wrote: {s}'
def sys_exit(code):
    return f'exit code {code}'
def sys_getpid():
    return 'pid 42'
table = {1: sys_write, 60: sys_exit, 39: sys_getpid}
calls = [(1, 'hello'), (39,), (60, 0), (999,)]
for c in calls:
    fn = table.get(c[0])
    print(f'call {c[0]}:', fn(*c[1:]) if fn else 'error: unknown syscall')

def task(name, n):
    for i in range(1, n + 1):
        yield f'{name} step {i}'
tasks = [task('A', 3), task('B', 3)]
active = tasks[:]
while active:
    nxt = []
    for t in active:
        try:
            print(next(t))
            nxt.append(t)
        except StopIteration:
            pass
    active = nxt
print('all tasks done')

mem = {}
header = {'magic': 0x464C4154, 'entry': 0x1000, 'segments': [(0x1000, b'CODE'), (0x2000, b'DATA')]}
assert header['magic'] == 0x464C4154, 'bad magic'
for addr, data in header['segments']:
    mem[addr] = data
    print(f'loaded {len(data)} bytes at {hex(addr)}')
print('entry point:', hex(header['entry']))
print('segments:', len(header['segments']))

rate = 100
targets = {50: 'beep', 100: 'reschedule', 250: 'second tick'}
for tick in range(1, 251):
    if tick in targets:
        ms = tick * 1000 // rate
        print(f'tick {tick} ({ms} ms): {targets[tick]}')
print('ticks run: 250, elapsed: 2500 ms')

def cmd_help(args):
    return 'commands: help echo ver add'
def cmd_echo(args):
    return ' '.join(args)
def cmd_ver(args):
    return 'minimal shell 1.0'
def cmd_add(args):
    if len(args) != 2:
        return 'error: add needs 2 numbers'
    try:
        return str(int(args[0]) + int(args[1]))
    except ValueError:
        return 'error: add needs numbers'
table = {'help': cmd_help, 'echo': cmd_echo, 'ver': cmd_ver, 'add': cmd_add}
lines = ['help', 'echo hello minimal pc', 'ver', 'add 20 22', 'frobnicate', 'add 1']
for line in lines:
    parts = line.split()
    fn = table.get(parts[0]) if parts else None
    print(f'> {line}')
    print(' ', fn(parts[1:]) if fn else 'error: unknown command')
